// Writes supabase/seed.sql from the fixture set. Tables do not exist yet (plan step 2),
// so the file records the set that the later INSERT seed will load. Do not edit seed.sql.
import { createHash } from 'node:crypto';
import { mkdirSync, writeFileSync } from 'node:fs';
import { register } from 'node:module';
import { dirname, join } from 'node:path';
import process from 'node:process';
import { fileURLToPath } from 'node:url';

const ROOT = join(dirname(fileURLToPath(import.meta.url)), '../..');
const DEFAULT_SEED = 20261025;

register(new globalThis.URL('../../tools/resolve-ts.mjs', import.meta.url));
const { DEFAULT_SEED: fixtureSeed, generateFixtures } = await import('@fa/fixtures');

if (fixtureSeed !== DEFAULT_SEED) {
  process.stderr.write('fixture DEFAULT_SEED drifted from the seed script\n');
  process.exit(1);
}

const set = generateFixtures(DEFAULT_SEED);
const lines = [
  '-- Generated by supabase/scripts/generate-seed.mjs. Do not edit.',
  '-- Step 2 adds the tables. Until then this file only records the fixture set.',
  `-- seed ${String(DEFAULT_SEED)}`,
];
const counts = {
  institutions: set.institutions.length,
  products: set.products.length,
  documents: set.documents.length,
  facts: set.facts.length,
  bank_metrics: set.bankMetrics.length,
  sponsored: set.sponsored.length,
};
for (const [name, count] of Object.entries(counts)) {
  lines.push(`-- ${name} ${String(count)}`);
}
const body = JSON.stringify(counts);
const digest = createHash('sha256').update(body).digest('hex').slice(0, 12);
lines.push(`-- sha256 ${digest}`);
lines.push('');

const dir = join(ROOT, 'supabase');
mkdirSync(dir, { recursive: true });
writeFileSync(join(dir, 'seed.sql'), lines.join('\n'));
process.stdout.write(`seed.sql: ${lines.length - 1} lines for seed ${String(DEFAULT_SEED)}\n`);
